(35061, 'Psalms 107:33', 'Psalms', 107, 33, 'هغه سیندونه کړل بدل په دښته او چینې د اوبو په وچه ځمکه باندې', 'هغه سیندونه کرل بدل په دشته او چینې د اوبو په وچه جمکه باندې', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_107_33.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237838, 1761237838),
(35062, 'Psalms 107:34', 'Psalms', 107, 34, 'هغه بدله کړله ښه حاصلخېزه ځمکه په ښوره زاره ځمکه د هغو خلکو د بدۍ په سبب چې هلته اوسي په کې', 'هغه بدله کرله شه حاصلخېزه جمکه په شوره زاره جمکه د هغو خلکو د بدی په سبب چې هلته اوسی په کې', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_107_34.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237838, 1761237838),
(35063, 'Psalms 107:35', 'Psalms', 107, 35, 'هغه بدله کړله دښته په ډنډونو باندې او کړلې یې بدلې وچې ځمکې په چینو باندې', 'هغه بدله کرله دشته په دندونو باندې او کرلې یې بدلې وچې جمکې په چینو باندې', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_107_35.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237838, 1761237838),
(35064, 'Psalms 107:36', 'Psalms', 107, 36, 'هلته یې راوستل وږي خلک چې په کې واوسیږي او هغوی ښار جوړ کړ چې په کې واوسیږي', 'هلته یې راوستل وزی خلک چې په کې واوسیزی او هغوی شار جور کر چې په کې واوسیزی', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_107_36.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237838, 1761237838),
(35065, 'Psalms 107:37', 'Psalms', 107, 37, 'هغوی کښېنول تاکونه او پټي یې وکرل او ډېر حاصل یې واخیست', 'هغوی کشېنول تاکونه او پتی یې وکرل او دېر حاصل یې واخیست', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_107_37.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237838, 1761237838),
(35066, 'Psalms 107:38', 'Psalms', 107, 38, 'خپل قوم ته یې ورکړ برکت او اولادونه یې زیات شول او هغه پرېنښودې چې کمې شي پادې او هم رمې د هغوی', 'خپل قوم ته یې ورکر برکت او اولادونه یې زیات شول او هغه پرېنشودې چې کمې شی پادې او هم رمې د هغوی', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_107_38.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237838, 1761237838),
(35067, 'Psalms 107:39', 'Psalms', 107, 39, 'کله چې وخوړله ماتې د خدای قوم او سپک شول هغوی د ظالمانو له خوا او ځورېدل هغوی', 'کله چې وخورله ماتې د خدای قوم او سپک شول هغوی د ظالمانو له خوا او جورېدل هغوی', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_107_39.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237838, 1761237838),
(35068, 'Psalms 107:40', 'Psalms', 107, 40, 'هغه سپک کړل ظالمان خلک او خوشې صحرا کې سرګردان کړل هغوی', 'هغه سپک کرل ظالمان خلک او خوشې صحرا کې سرګردان کرل هغوی', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_107_40.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237838, 1761237838),
(35069, 'Psalms 107:41', 'Psalms', 107, 41, 'خو محتاج خلک یې بدبختۍ نه خلاص کړل او کورنۍ یې ورته زیاتې کړلې لکه رمو په شان', 'خو محتاج خلک یې بدبختی نه خلاص کرل او کورنی یې ورته زیاتې کرلې لکه رمو په شان', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_107_41.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237838, 1761237838),
(35070, 'Psalms 107:42', 'Psalms', 107, 42, 'صادقان خلک چې دا ګوري نو کوي خوشحالي خو ټول بدکاره خلک چوپ پاتې شي', 'صادقان خلک چې دا ګوری نو کوی خوشحالی خو تول بدکاره خلک چوپ پاتې شی', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_107_42.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237838, 1761237838),
(35071, 'Psalms 107:43', 'Psalms', 107, 43, 'څوک چې هوښیار وي نو غور دې وکړي دې خبرو باندې فکر دې وکړي د څښتن د تلپاتې مینې په باب', 'چوک چې هوشیار وی نو غور دې وکری دې خبرو باندې فکر دې وکری د چشتن د تلپاتې مینې په باب', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_107_43.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237838, 1761237838),
(35072, 'Psalms 130:1', 'Psalms', 130, 1, 'د ډېرې زیاتې مایوسۍ نه کړم فریاد تاته ای څښتنه', 'د دېرې زیاتې مایوسی نه کرم فریاد تاته ای چشتنه', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_130_1.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237838, 1761237838),
(35073, 'Psalms 130:2', 'Psalms', 130, 2, 'زما زارۍ واوره ای څښتنه فریاد مې واوره د کومک په خاطر', 'زما زاری واوره ای چشتنه فریاد مې واوره د کومک په خاطر', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_130_2.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237838, 1761237838),
(35074, 'Psalms 130:3', 'Psalms', 130, 3, 'که مو حساب د ګناهونو وکړې ای څښتنه نو څوک ستا مخکې ودرېدلی شي؟', 'که مو حساب د ګناهونو وکرې ای چشتنه نو چوک ستا مخکې ودرېدلی شی؟', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_130_3.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237838, 1761237838),
(35075, 'Psalms 130:4', 'Psalms', 130, 4, 'خو ته بخښونکی یې نو باید مونږ ووېرېږو ستا څخه', 'خو ته بخشونکی یې نو باید مونز ووېرېزو ستا چخه', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_130_4.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237838, 1761237838),
(35076, 'Psalms 130:5', 'Psalms', 130, 5, 'زه څښتن ته انتظار کومه زه په خپله انتظار کومه او په کلام یې زه باور لرمه', 'زه چشتن ته انتظار کومه زه په خپله انتظار کومه او په کلام یې زه باور لرمه', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_130_5.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237838, 1761237838),
(35077, 'Psalms 130:6', 'Psalms', 130, 6, 'زه انتظار کوم څښتن دپاره د دې نه زیات انتظار چې پهره‌دار یې تر سهاره کوي د دې نه زیات انتظار چې پهره‌دار یې تر سهاره کوي', 'زه انتظار کوم چشتن دپاره د دې نه زیات انتظار چې پهره‌دار یې تر سهاره کوی د دې نه زیات انتظار چې پهره‌دار یې تر سهاره کوی', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_130_6.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237838, 1761237838),
(35078, 'Psalms 130:7', 'Psalms', 130, 7, 'ای اسراییلو، په څښتن باندې باور ولرئ ځکه چې مینه یې تلپاتې ده او هغه راضي دی همېشه چې درکړي خلاصون', 'ای اسراییلو، په چشتن باندې باور ولری جکه چې مینه یې تلپاتې ده او هغه راضی دی همېشه چې درکری خلاصون', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_130_7.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237838, 1761237838),
(35079, 'Psalms 130:8', 'Psalms', 130, 8, 'هغه په خپله به خپل قوم اسراییل له خپلو ټولو ګناهونو خلاص کړي', 'هغه په خپله به خپل قوم اسراییل له خپلو تولو ګناهونو خلاص کری', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_130_8.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237838, 1761237838),
(35080, 'Numbers 36:1', 'Numbers', 36, 1, 'یوه ورځ د جلعاد د طایفې د کورنیو مشران موسی او د اسراییلو نورو مشرانو ته ورغلل. (جلعاد د ماخیر زوی، ماخیر د منسي زوی او منسي د یوسف زوی ؤ.)', 'یوه ورج د جلعاد د طایفې د کورنیو مشران موسی او د اسراییلو نورو مشرانو ته ورغلل. (جلعاد د ماخیر زوی، ماخیر د منسی زوی او منسی د یوسف زوی و.)', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_36_1.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237838, 1761237838),
(35081, 'Numbers 36:2', 'Numbers', 36, 2, 'هغوی وویل: «باداره، څښتن تاته حکم کړی دی چې د اسراییلو خلکو ته د پچې له مخې ځمکه ووېشې. همدارنګه هغه حکم کړی دی چې زمونږ د خپلوان صلفحاد ځمکه د هغه لورګانو ته ورکړې.', 'هغوی وویل: «باداره، چشتن تاته حکم کری دی چې د اسراییلو خلکو ته د پچې له مخې جمکه ووېشې. همدارنګه هغه حکم کری دی چې زمونز د خپلوان صلفحاد جمکه د هغه لورګانو ته ورکرې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_36_2.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237838, 1761237838),
(35082, 'Numbers 36:3', 'Numbers', 36, 3, 'خو دا خبره یاد ساته، که چېرې هغوی د بلې قبیلې د سړیو سره ودونه وکړي، د هغوی جایداد به د هماغې قبیلې شي او زمونږ دپاره ټاکل شوې برخه به کمه شي.', 'خو دا خبره یاد ساته، که چېرې هغوی د بلې قبیلې د سریو سره ودونه وکری، د هغوی جایداد به د هماغې قبیلې شی او زمونز دپاره تاکل شوې برخه به کمه شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_36_3.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237838, 1761237838),
(35083, 'Numbers 36:4', 'Numbers', 36, 4, 'د بېرته ورکولو په کال کې کله چې ټول خرڅ شوی جایداد خپل اصلي خاوند ته بېرته ورکړل شي، د صلفحاد د لورګانو ځمکه به د هغې قبیلې په تلپاتې جایداد باندې ورزیاته شي په کومې کې چې هغوی واده شوې دي او دا به زمونږ د قبیلې په تاوان تمام شي.»', 'د بېرته ورکولو په کال کې کله چې تول خرچ شوی جایداد خپل اصلی خاوند ته بېرته ورکرل شی، د صلفحاد د لورګانو جمکه به د هغې قبیلې په تلپاتې جایداد باندې ورزیاته شی په کومې کې چې هغوی واده شوې دی او دا به زمونز د قبیلې په تاوان تمام شی.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_36_4.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237838, 1761237838),
(35084, 'Numbers 36:5', 'Numbers', 36, 5, 'نو موسی د څښتن له خوا د اسراییلو قوم ته دغه حکم ورکړ. هغه وویل: «د منسي قبیله چې څه وایي هغه سم دي', 'نو موسی د چشتن له خوا د اسراییلو قوم ته دغه حکم ورکر. هغه وویل: «د منسی قبیله چې چه وایی هغه سم دی', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_36_5.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237838, 1761237838),
(35085, 'Numbers 36:6', 'Numbers', 36, 6, 'او څښتن وایي چې د صلفحاد لورګانې ازادې دي چې د هرچا سره چې وغواړي واده کولای شي، خو یوازې په خپله قبیله کې.', 'او چشتن وایی چې د صلفحاد لورګانې ازادې دی چې د هرچا سره چې وغواری واده کولای شی، خو یوازې په خپله قبیله کې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_36_6.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237838, 1761237838),
(35086, 'Numbers 36:7', 'Numbers', 36, 7, 'په دې ډول به د هر اسراییلي جایداد د هغه د خپلې قبیلې پورې تړلی پاتې شي.', 'په دې دول به د هر اسراییلی جایداد د هغه د خپلې قبیلې پورې ترلی پاتې شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_36_7.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237838, 1761237838),
(35087, 'Numbers 36:8', 'Numbers', 36, 8, 'هره ښځه چې د اسراییلو په یوه قبیله کې ځمکه په میراث اخلي باید د هماغې قبیلې د سړي سره واده وکړي. په دې ډول به ټولو اسراییلیانو ته د خپلو نیکونو جایداد په میراث کې ورسیږي', 'هره شجه چې د اسراییلو په یوه قبیله کې جمکه په میراث اخلی باید د هماغې قبیلې د سری سره واده وکری. په دې دول به تولو اسراییلیانو ته د خپلو نیکونو جایداد په میراث کې ورسیزی', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_36_8.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237838, 1761237838),
(35088, 'Numbers 36:9', 'Numbers', 36, 9, 'او د یوې قبیلې ځمکه دې بلې قبیلې ته نه ورکول کیږي. هره قبیله دې خپل ملکیت وساتي.»', 'او د یوې قبیلې جمکه دې بلې قبیلې ته نه ورکول کیزی. هره قبیله دې خپل ملکیت وساتی.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_36_9.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237838, 1761237838),
(35089, 'Numbers 36:12', 'Numbers', 36, 12, 'او د منسي په قبیلې کې پاتې شوې. نو د هغوی جایداد د هغوی د پلار په قبیله کې پاتې شو.', 'او د منسی په قبیلې کې پاتې شوې. نو د هغوی جایداد د هغوی د پلار په قبیله کې پاتې شو.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_36_12.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237838, 1761237838),
(35090, 'Numbers 36:13', 'Numbers', 36, 13, 'دا هغه اصول او مقررات دي چې څښتن د موسی په وسیله د موآب په ډاګونو کې د اردن د سیند په بله غاړه اریحا ته مخامخ اسراییلیانو ته ورکړل.', 'دا هغه اصول او مقررات دی چې چشتن د موسی په وسیله د مواب په داګونو کې د اردن د سیند په بله غاره اریحا ته مخامخ اسراییلیانو ته ورکرل.', 'OT', 'afghan2023', 'afghan', '', '', 1761237838, 1761237838),
(35091, 'Proverbs 29:1', 'Proverbs', 29, 1, 'څوک چې د ډېرې رټنې نه وروسته بیا هم سرغړونه کوي نو ناڅاپه به ټوټې ټوټې شي او د جوړېدو به نه وي.', 'چوک چې د دېرې رتنې نه وروسته بیا هم سرغرونه کوی نو ناچاپه به توتې توتې شی او د جورېدو به نه وی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs029_verse_001.mp3', 'https://drive.google.com/uc?id=1VGVUTWc68wb75LS2VnXIUmMsBe5mwRhf&export=download', 1761237838, 1761237838),
(35092, 'Proverbs 29:2', 'Proverbs', 29, 2, 'کله چې نېکان ابادیږي نو ټول خلک خوشحالیږي خو کله چې بدکاران واک ته رسیږي نو خلک خفه کیږي.', 'کله چې نېکان ابادیزی نو تول خلک خوشحالیزی خو کله چې بدکاران واک ته رسیزی نو خلک خفه کیزی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs029_verse_002.mp3', 'https://drive.google.com/file/d/1nI_wySa-adWMYU7rz7jBiAeAT3GzSjAP/preview', 1761237838, 1761237838),
